#requires -Version 5.1
<#
GDebloat: the uploaded GDebloat.ps1, renamed and edited in place.
Original removal, ownership, WinSxS copy/delete, WIM rebuild and ISO methods remain.
Driver/audio/Store/Xbox/installer exceptions are applied to its original lists.
All registry mutation stages and policy tweaks are omitted. No extra health or
per-file reparse checks are added. Windows runtime functionality is unverified.
Source SHA256: 46254253E4B18470221DFF828C7F1F5BBB0B4339C3369571AD7F4BBA9D22F20B
#>
[CmdletBinding()]
param(
 [string]$SourceIso,
 [int]$ImageIndex = 0,
 [string]$OutputIso,
 [ValidatePattern('^[A-Za-z]:\\?$')][string]$WorkDirectory,
 [string]$OscdimgPath,
 [string]$DriverDirectory,
 [string]$GSecurityDirectory,
 [string]$NetFx3Source,
 [switch]$SkipAutoDrivers,
 [switch]$SkipGSecurity
)
# Initialize runtime paths after parameter binding (Windows PowerShell 5.1).
if ([string]::IsNullOrWhiteSpace($OutputIso)) {
 $OutputIso = Join-Path $PSScriptRoot 'GDebloat.iso'
}
if ([string]::IsNullOrWhiteSpace($WorkDirectory)) {
 $WorkDirectory = [IO.Path]::GetPathRoot($env:SystemRoot)
}
# End runtime path initialization.
if ([Environment]::OSVersion.Platform -ne 'Win32NT' -or -not [Environment]::Is64BitProcess) {
 throw 'Use elevated 64-bit Windows PowerShell.'
}
$OutputIso = [IO.Path]::GetFullPath($OutputIso)
if (Test-Path -LiteralPath $OutputIso) { throw "Output already exists: $OutputIso. Choose another -OutputIso." }
# Full console colour palette:
# 🌸 Magenta · 🩵 Cyan/Aqua · 🔵 Blue · 💚 Green · 💛 Yellow · 🩶 Gray · 🧡 Orange · 💜 Light Violet
# ============================================================================
# Console presentation: section headers + completion footers only; section bodies are silent.
# Original Micro section-level output suppression is preserved.
function Select-WimImageIndex {
 param(
 [Parameter(Mandatory = $true)]
 [string]$ImagePath
 )

 $images = @(Get-WindowsImage -ImagePath $ImagePath -ErrorAction Stop)

 if ($images.Count -eq 0) {
 throw "No image indexes were found in: $ImagePath"
 }

 if ($images.Count -eq 1) {
 $selectedIndex = [int]$images[0].ImageIndex
 Write-Host "Only one image index was found. Automatically selecting Index: $selectedIndex"
 return $selectedIndex
 }

 Write-Host "Multiple image indexes were found. Please select the index you want to use."

 foreach ($image in $images) {
 Write-Host ("Index: {0} - {1}" -f $image.ImageIndex, $image.ImageName)
 }

 do {
 $selectedIndex = Read-Host "Please enter the image index"

 $parsedIndex = 0
 $validNumber = [int]::TryParse([string]$selectedIndex, [ref]$parsedIndex)
 $validIndex = if ($validNumber) { $images | Where-Object { $_.ImageIndex -eq $parsedIndex } } else { $null }

 if ($null -eq $validIndex) {
 Write-Warning "Invalid index. Please enter one of the indexes listed above."
 }
 }
 until ($null -ne $validIndex)

 return [int]$selectedIndex
}


# Check and run the script as admin if required
$adminSID = New-Object System.Security.Principal.SecurityIdentifier("S-1-5-32-544")
$adminGroup = $adminSID.Translate([System.Security.Principal.NTAccount])
$myWindowsID=[System.Security.Principal.WindowsIdentity]::GetCurrent()
$myWindowsPrincipal=new-object System.Security.Principal.WindowsPrincipal($myWindowsID)
$adminRole=[System.Security.Principal.WindowsBuiltInRole]::Administrator
if (! $myWindowsPrincipal.IsInRole($adminRole))
{
 Write-Host "Restarting GDebloat image creator as admin in a new window, you can close this one."
 $newProcess = new-object System.Diagnostics.ProcessStartInfo "PowerShell";
 $newProcess.Arguments = '-NoProfile -ExecutionPolicy Bypass -File "{0}"' -f $MyInvocation.MyCommand.Definition;
 foreach ($parameterName in @('SourceIso','OutputIso','WorkDirectory','OscdimgPath','DriverDirectory','GSecurityDirectory','NetFx3Source')) {
  if ($PSBoundParameters.ContainsKey($parameterName)) {
   $newProcess.Arguments += ' -{0} "{1}"' -f $parameterName, $PSBoundParameters[$parameterName]
  }
 }
 if ($SkipAutoDrivers) { $newProcess.Arguments += ' -SkipAutoDrivers' }
 if ($SkipGSecurity) { $newProcess.Arguments += ' -SkipGSecurity' }
 if ($PSBoundParameters.ContainsKey('ImageIndex')) { $newProcess.Arguments += ' -ImageIndex {0}' -f $ImageIndex }

 $newProcess.Verb = "runas";
 [System.Diagnostics.Process]::Start($newProcess);
 exit
}
# Micro's original short drive-root paths: C:\scratchdir and C:\GDebloat.
$mainOSDrive = $WorkDirectory.TrimEnd('\')
foreach ($existing in @("$mainOSDrive\scratchdir", "$mainOSDrive\GDebloat")) {
 if (Test-Path -LiteralPath $existing) {
  throw "Existing Micro working path: $existing. Preserve or clear that previous build before starting; it will not be overwritten."
 }
}
Start-Transcript -Path (Join-Path $PSScriptRoot ('GDebloat-' + [guid]::NewGuid().ToString('N') + '.log'))
Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "                 WELCOME TO GDEBLOAT - MICRO BASE" -ForegroundColor Cyan
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "                 Windows Image Optimization & Cleanup" -ForegroundColor Cyan
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host ""
    # output suppressed
    # output suppressed
# Micro drive-root mainOSDrive was selected before transcript startup.
$scratchDir = "$mainOSDrive\scratchdir"


# ============================================================================
# ROBUST OFFLINE-IMAGE HELPERS
# ============================================================================
# These helpers prevent stale DISM mount registrations and registry hive locks
# from allowing the script to continue after a failed operation.
# ============================================================================

function Invoke-RegUnloadWithRetry {
 param(
 [Parameter(Mandatory = $true)]
 [string]$HiveName,
 [int]$Attempts = 30,
 [int]$DelayMilliseconds = 500
 )

 $hivePath = "HKLM\$HiveName"

 for ($attempt = 1; $attempt -le $Attempts; $attempt++) {
 & reg.exe unload $hivePath > $null 2>&1
 $exitCode = $LASTEXITCODE

 if ($exitCode -eq 0) {
 return $true
 }

 [GC]::Collect()
 [GC]::WaitForPendingFinalizers()
 Start-Sleep -Milliseconds $DelayMilliseconds
 }

 return $false
}


# ============================================================================
# NATIVE REGISTRY HIVE SAVE / PHYSICAL COMPACTION
# ============================================================================
function Get-Micro11NativeRegistryApi {
 if ($script:Micro11NativeRegistryApi) {
 return $script:Micro11NativeRegistryApi
 }

 $assemblyName = New-Object System.Reflection.AssemblyName('Micro11.NativeRegistry.Dynamic')
 $assembly = [AppDomain]::CurrentDomain.DefineDynamicAssembly(
 $assemblyName,
 [System.Reflection.Emit.AssemblyBuilderAccess]::Run
 )
 $module = $assembly.DefineDynamicModule('Micro11.NativeRegistry.Dynamic.Module')

 $typeAttributes = [System.Reflection.TypeAttributes]::Public -bor
 [System.Reflection.TypeAttributes]::Sealed -bor
 [System.Reflection.TypeAttributes]::Abstract
 $typeBuilder = $module.DefineType('Micro11.NativeRegistry.Win32', $typeAttributes)

 function Add-Micro11PInvokeMethod {
 param(
 [Parameter(Mandatory = $true)] [string]$Name,
 [Parameter(Mandatory = $true)] [string]$Dll,
 [Parameter(Mandatory = $true)] [Type]$ReturnType,
 [AllowEmptyCollection()] [Type[]]$ParameterTypes = [Type[]]@(),
 [System.Runtime.InteropServices.CharSet]$CharSet = [System.Runtime.InteropServices.CharSet]::Unicode
 )

 # PowerShell can treat a positional @() as an omitted argument during
 # parameter binding. Reflection.Emit, however, must receive an actual
 # Type[] (including a zero-length Type[]) for a zero-argument Win32 API.
 # Normalize it here so DefinePInvokeMethod always receives a real array.
 if ($null -eq $ParameterTypes) {
 $ParameterTypes = [Type[]]@()
 } else {
 $ParameterTypes = [Type[]]$ParameterTypes
 }

 $attrs = [System.Reflection.MethodAttributes]::Public -bor
 [System.Reflection.MethodAttributes]::Static -bor
 [System.Reflection.MethodAttributes]::PinvokeImpl

 $method = $typeBuilder.DefinePInvokeMethod(
 $Name,
 $Dll,
 $attrs,
 [System.Reflection.CallingConventions]::Standard,
 $ReturnType,
 $ParameterTypes,
 [System.Runtime.InteropServices.CallingConvention]::Winapi,
 $CharSet
 )
 $method.SetImplementationFlags(
 $method.GetMethodImplementationFlags() -bor
 [System.Reflection.MethodImplAttributes]::PreserveSig
 )
 }

 $intPtrByRef = [IntPtr].MakeByRefType()

 Add-Micro11PInvokeMethod -Name 'GetCurrentProcess' -Dll 'kernel32.dll' -ReturnType ([IntPtr]) -ParameterTypes ([Type[]]@()) -CharSet ([System.Runtime.InteropServices.CharSet]::None)
 Add-Micro11PInvokeMethod -Name 'CloseHandle' -Dll 'kernel32.dll' -ReturnType ([bool]) -ParameterTypes ([Type[]]@([IntPtr])) -CharSet ([System.Runtime.InteropServices.CharSet]::None)
 Add-Micro11PInvokeMethod -Name 'OpenProcessToken' -Dll 'advapi32.dll' -ReturnType ([bool]) -ParameterTypes ([Type[]]@([IntPtr],[uint32],$intPtrByRef)) -CharSet ([System.Runtime.InteropServices.CharSet]::None)
 Add-Micro11PInvokeMethod -Name 'LookupPrivilegeValueW' -Dll 'advapi32.dll' -ReturnType ([bool]) -ParameterTypes ([Type[]]@([string],[string],[IntPtr]))
 Add-Micro11PInvokeMethod -Name 'AdjustTokenPrivileges' -Dll 'advapi32.dll' -ReturnType ([bool]) -ParameterTypes ([Type[]]@([IntPtr],[bool],[IntPtr],[uint32],[IntPtr],[IntPtr])) -CharSet ([System.Runtime.InteropServices.CharSet]::None)
 Add-Micro11PInvokeMethod -Name 'RegOpenKeyExW' -Dll 'advapi32.dll' -ReturnType ([int]) -ParameterTypes ([Type[]]@([IntPtr],[string],[uint32],[uint32],$intPtrByRef))
 Add-Micro11PInvokeMethod -Name 'RegDeleteTreeW' -Dll 'advapi32.dll' -ReturnType ([int]) -ParameterTypes ([Type[]]@([IntPtr],[string])) -CharSet ([System.Runtime.InteropServices.CharSet]::Unicode)
 Add-Micro11PInvokeMethod -Name 'RegSaveKeyExW' -Dll 'advapi32.dll' -ReturnType ([int]) -ParameterTypes ([Type[]]@([IntPtr],[string],[IntPtr],[uint32]))
 Add-Micro11PInvokeMethod -Name 'RegCloseKey' -Dll 'advapi32.dll' -ReturnType ([int]) -ParameterTypes ([Type[]]@([IntPtr])) -CharSet ([System.Runtime.InteropServices.CharSet]::None)

 $script:Micro11NativeRegistryApi = $typeBuilder.CreateType()
 return $script:Micro11NativeRegistryApi
}

function Invoke-Micro11EnableBackupPrivilege {
 param([Parameter(Mandatory = $true)] [Type]$Api)

 # The nuclear offline-hive deletion needs more than SeBackupPrivilege.
 # SeTakeOwnershipPrivilege and SeRestorePrivilege are enabled so protected
 # Registry keys can have their owner/DACL changed before recursive deletion.
 $privileges = @('SeBackupPrivilege','SeTakeOwnershipPrivilege','SeRestorePrivilege')
 $token = [IntPtr]::Zero

 try {
 $process = $Api.GetMethod('GetCurrentProcess').Invoke($null, @())
 $openArgs = [object[]]@([IntPtr]$process, [uint32]0x28, [IntPtr]::Zero)
 $opened = [bool]$Api.GetMethod('OpenProcessToken').Invoke($null, $openArgs)
 $token = [IntPtr]$openArgs[2]
 if (-not $opened -or $token -eq [IntPtr]::Zero) {
 throw 'OpenProcessToken failed. Run the script from an elevated PowerShell session.'
 }

 foreach ($privilege in $privileges) {
 $luid = [Runtime.InteropServices.Marshal]::AllocHGlobal(8)
 $tp = [Runtime.InteropServices.Marshal]::AllocHGlobal(16)
 try {
 [Runtime.InteropServices.Marshal]::WriteInt64($luid, 0, 0)
 $lookupArgs = [object[]]@($null, $privilege, $luid)
 $lookedUp = [bool]$Api.GetMethod('LookupPrivilegeValueW').Invoke($null, $lookupArgs)
 if (-not $lookedUp) { throw "LookupPrivilegeValueW failed for $privilege." }

 for ($i = 0; $i -lt 16; $i += 4) {
 [Runtime.InteropServices.Marshal]::WriteInt32($tp, $i, 0)
 }
 [Runtime.InteropServices.Marshal]::WriteInt32($tp, 0, 1)
 [Runtime.InteropServices.Marshal]::WriteInt32($tp, 4, [Runtime.InteropServices.Marshal]::ReadInt32($luid, 0))
 [Runtime.InteropServices.Marshal]::WriteInt32($tp, 8, [Runtime.InteropServices.Marshal]::ReadInt32($luid, 4))
 [Runtime.InteropServices.Marshal]::WriteInt32($tp, 12, 0x2)

 $adjustArgs = [object[]]@($token, $false, $tp, [uint32]0, [IntPtr]::Zero, [IntPtr]::Zero)
 $adjusted = [bool]$Api.GetMethod('AdjustTokenPrivileges').Invoke($null, $adjustArgs)
 if (-not $adjusted) { throw "AdjustTokenPrivileges failed for $privilege." }
 }
 finally {
 if ($tp -ne [IntPtr]::Zero) { [Runtime.InteropServices.Marshal]::FreeHGlobal($tp) }
 if ($luid -ne [IntPtr]::Zero) { [Runtime.InteropServices.Marshal]::FreeHGlobal($luid) }
 }
 }
 }
 finally {
 if ($token -ne [IntPtr]::Zero) {
 [void]$Api.GetMethod('CloseHandle').Invoke($null, [object[]]@($token))
 }
 }
}

function Invoke-NativeRegistryHiveSaveLatest {
 param(
 [Parameter(Mandatory = $true)] [string]$HiveName,
 [Parameter(Mandatory = $true)] [string]$DestinationPath
 )

 Remove-Item -LiteralPath $DestinationPath -Force -ErrorAction SilentlyContinue

 $api = $null
 $key = [IntPtr]::Zero

 try {
 $api = Get-Micro11NativeRegistryApi
 Invoke-Micro11EnableBackupPrivilege -Api $api

 $hklm = [IntPtr]([int64]-2147483646) # HKEY_LOCAL_MACHINE / 0xFFFFFFFF80000002
 $samDesired = [uint32](0x20019 -bor 0x0100) # KEY_READ | KEY_WOW64_64KEY
 $openArgs = [object[]]@($hklm, [string]$HiveName, [uint32]0, $samDesired, [IntPtr]::Zero)
 $openResult = [int]$api.GetMethod('RegOpenKeyExW').Invoke($null, $openArgs)
 $key = [IntPtr]$openArgs[4]
 if ($openResult -ne 0 -or $key -eq [IntPtr]::Zero) {
 throw "RegOpenKeyExW failed for HKLM\$HiveName (Win32 code $openResult)."
 }

 # REG_LATEST_FORMAT = 2. The destination must not already exist.
 $saveArgs = [object[]]@($key, $DestinationPath, [IntPtr]::Zero, [uint32]2)
 $saveResult = [int]$api.GetMethod('RegSaveKeyExW').Invoke($null, $saveArgs)
 if ($saveResult -ne 0) {
 throw "RegSaveKeyExW(REG_LATEST_FORMAT) failed for HKLM\$HiveName (Win32 code $saveResult)."
 }

 if (-not (Test-Path -LiteralPath $DestinationPath -PathType Leaf)) {
 throw "RegSaveKeyExW reported success but did not create $DestinationPath."
 }

 Write-Host " Native in-process RegSaveKeyEx(REG_LATEST_FORMAT) succeeded for HKLM\$HiveName." -ForegroundColor Green
 return 0
 }
 catch {
 Write-Warning ("Native RegSaveKeyExW compaction failed for HKLM\{0}: {1}" -f $HiveName, $_.Exception.Message)
 }
 finally {
 if ($null -ne $api -and $key -ne [IntPtr]::Zero) {
 try { [void]$api.GetMethod('RegCloseKey').Invoke($null, [object[]]@($key)) } catch {}
 }
 }

 # Safe fallback only. This keeps the script functional on unusual hosts,
 # but the log explicitly reports that maximum physical compaction was not
 # available instead of pretending REG.EXE SAVE is equivalent.
 Remove-Item -LiteralPath $DestinationPath -Force -ErrorAction SilentlyContinue
 Write-Warning "Falling back to reg.exe SAVE for HKLM\$HiveName. Maximum physical hive compaction was not available."
 & reg.exe save "HKLM\$HiveName" $DestinationPath /y 2>&1 | ForEach-Object {
 if ($_ -and $_.ToString().Trim()) { Write-Warning $_.ToString() }
 }
 return $LASTEXITCODE
}

function Invoke-DismUnmountDiscardIfMounted {
 param(
 [Parameter(Mandatory = $true)]
 [string]$MountDir
 )

 $normalizedMountDir = [System.IO.Path]::GetFullPath($MountDir).TrimEnd('\')
 $mountedInfo = & dism.exe /English /Get-MountedWimInfo 2>&1
 $mountedCode = $LASTEXITCODE
 $mountedText = ($mountedInfo -join [Environment]::NewLine)

 if ($mountedCode -ne 0) {
  Write-Warning "DISM /Get-MountedWimInfo returned exit code $mountedCode. Running DISM mount-point cleanup..."
  & dism.exe /English /Cleanup-Mountpoints 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
  $cleanupMountpointsCode = $LASTEXITCODE
  & dism.exe /English /Cleanup-Wim 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
  $cleanupWimCode = $LASTEXITCODE
  Start-Sleep -Seconds 2
  $mountedInfo = & dism.exe /English /Get-MountedWimInfo 2>&1
  $mountedCode = $LASTEXITCODE
  $mountedText = ($mountedInfo -join [Environment]::NewLine)
 }

 if ($mountedText -match [regex]::Escape($MountDir)) {
  Write-Warning "DISM reports an image mounted at $MountDir. Attempting recovery before discard..."

  # First try the normal DISM recovery path.
  & dism.exe /English /Remount-Image "/MountDir:$MountDir" 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
  $remountCode = $LASTEXITCODE
  if ($remountCode -eq 0) {
   Write-Host "DISM mount point remounted successfully; proceeding with discard..." -ForegroundColor Yellow
   Start-Sleep -Seconds 1
  }
  else {
   Write-Warning "DISM /Remount-Image returned exit code $remountCode. Continuing with cleanup/discard recovery."
  }

  & dism.exe /English /Unmount-Image "/MountDir:$MountDir" /Discard 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
  $unmountCode = $LASTEXITCODE

  if ($unmountCode -ne 0) {
   Write-Warning "DISM discard unmount failed for $MountDir (exit code $unmountCode). Running /Cleanup-Mountpoints and /Cleanup-Wim, then retrying..."

   & dism.exe /English /Cleanup-Mountpoints 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
   $cleanupMountpointsCode = $LASTEXITCODE
   & dism.exe /English /Cleanup-Wim 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
   $cleanupWimCode = $LASTEXITCODE
   Start-Sleep -Seconds 2

   & dism.exe /English /Unmount-Image "/MountDir:$MountDir" /Discard 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
   $retryCode = $LASTEXITCODE

   $verifyInfo = & dism.exe /English /Get-MountedWimInfo 2>&1
   $verifyText = ($verifyInfo -join [Environment]::NewLine)

   if (($retryCode -ne 0) -and ($verifyText -match [regex]::Escape($MountDir))) {
    # 0xC1420117 means DISM could not completely unmount the directory. At
    # startup this can be an orphaned WIMMount registration left by a crashed
    # previous run. Do NOT delete the whole WIMMount registry tree: locate only
    # the registry entry whose Mount Path exactly matches our mount directory.
    Write-Warning "DISM still reports $MountDir after discard/cleanup. Checking the WIMMount registry for an orphaned entry matching this mount only..."

    $wimMountRoot = 'Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\WIMMount\Mounted Images'
    $removedOrphan = $false

    if (Test-Path -LiteralPath $wimMountRoot) {
     foreach ($entry in @(Get-ChildItem -LiteralPath $wimMountRoot -ErrorAction SilentlyContinue)) {
      try {
       $props = Get-ItemProperty -LiteralPath $entry.PSPath -ErrorAction Stop
       $entryMountPath = [string]$props.'Mount Path'
       if ([string]::IsNullOrWhiteSpace($entryMountPath)) { continue }

       try {
        $normalizedEntryPath = [System.IO.Path]::GetFullPath($entryMountPath).TrimEnd('\')
       }
       catch {
        $normalizedEntryPath = $entryMountPath.TrimEnd('\')
       }

       if ([string]::Equals($normalizedEntryPath, $normalizedMountDir, [System.StringComparison]::OrdinalIgnoreCase)) {
        Write-Warning "Removing orphaned WIMMount registration for ${MountDir}: $($entry.PSChildName)"
        Remove-Item -LiteralPath $entry.PSPath -Recurse -Force -ErrorAction Stop
        $removedOrphan = $true
       }
      }
      catch {
       Write-Warning "Could not inspect/remove WIMMount entry '$($entry.PSPath)': $($_.Exception.Message)"
      }
     }
    }

    if ($removedOrphan) {
     Start-Sleep -Seconds 1
     & dism.exe /English /Cleanup-Mountpoints 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
     $cleanupMountpointsCode = $LASTEXITCODE
     & dism.exe /English /Cleanup-Wim 2>&1 | ForEach-Object { if ($_.ToString().Trim()) { Write-Warning $_.ToString() } }
     $cleanupWimCode = $LASTEXITCODE
     Start-Sleep -Seconds 2

     $postRegistryInfo = & dism.exe /English /Get-MountedWimInfo 2>&1
     $postRegistryText = ($postRegistryInfo -join [Environment]::NewLine)

     if ($postRegistryText -match [regex]::Escape($MountDir)) {
      throw "A stale DISM mount exists at $MountDir after targeted WIMMount registry recovery. Initial exit code: $unmountCode; Remount exit code: $remountCode; Cleanup-Mountpoints exit code: $cleanupMountpointsCode; Cleanup-Wim exit code: $cleanupWimCode; retry exit code: $retryCode"
     }
    }
    else {
     throw "A stale DISM mount exists at $MountDir and could not be discarded. No orphaned WIMMount registry entry matched this mount. Initial exit code: $unmountCode; Remount exit code: $remountCode; Cleanup-Mountpoints exit code: $cleanupMountpointsCode; Cleanup-Wim exit code: $cleanupWimCode; retry exit code: $retryCode"
    }
   }
  }
 }

 Start-Sleep -Seconds 1
 $finalInfo = & dism.exe /English /Get-MountedWimInfo 2>&1
 $finalText = ($finalInfo -join [Environment]::NewLine)
 if ($finalText -match [regex]::Escape($MountDir)) {
  throw "DISM still reports $MountDir as mounted after all automatic recovery attempts."
 }
}

function Clear-EmptyMountDirectory {
 param(
 [Parameter(Mandatory = $true)]
 [string]$MountDir
 )

 Invoke-DismUnmountDiscardIfMounted -MountDir $MountDir

 if (Test-Path -LiteralPath $MountDir) {
 $items = @(Get-ChildItem -LiteralPath $MountDir -Force -ErrorAction SilentlyContinue)
 if ($items.Count -gt 0) {
 Write-Host "Clearing residual files from mount directory: $MountDir"
 foreach ($item in $items) {
 Remove-Item -LiteralPath $item.FullName -Recurse -Force -ErrorAction Stop
 }
 }
 }
 else {
 New-Item -ItemType Directory -Path $MountDir -Force -ErrorAction Stop | Out-Null
 }
}

function Wait-ForFileUnlock {
 param(
 [Parameter(Mandatory = $true)]
 [string]$Path,
 [int]$Attempts = 30,
 [int]$DelayMilliseconds = 500
 )

 for ($attempt = 1; $attempt -le $Attempts; $attempt++) {
 if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
 return $true
 }

 try {
 $stream = [System.IO.File]::Open(
 $Path,
 [System.IO.FileMode]::Open,
 [System.IO.FileAccess]::ReadWrite,
 [System.IO.FileShare]::None
 )
 $stream.Dispose()
 return $true
 }
 catch {
 Start-Sleep -Milliseconds $DelayMilliseconds
 }
 }

 return $false
}
# Optional local payload discovery; no downloads or network installation.
if (-not $DriverDirectory -and -not $SkipAutoDrivers) {
 $candidate = Join-Path $PSScriptRoot 'Drivers'
 if (Test-Path -LiteralPath $candidate -PathType Container) { $DriverDirectory = $candidate }
}
if ($SkipAutoDrivers) { $DriverDirectory = $null }
if ($DriverDirectory) {
 $DriverDirectory = (Resolve-Path -LiteralPath $DriverDirectory -ErrorAction Stop).Path
 if (-not (Get-ChildItem -LiteralPath $DriverDirectory -Filter '*.inf' -Recurse -File)) {
  Write-Warning "No INF packages found under $DriverDirectory; driver injection skipped."
  $DriverDirectory = $null
 }
}
if (-not $GSecurityDirectory -and -not $SkipGSecurity) {
 $candidate = Join-Path $PSScriptRoot 'GSecurity'
 if (Test-Path -LiteralPath $candidate -PathType Container) { $GSecurityDirectory = $candidate }
}
if ($SkipGSecurity) { $GSecurityDirectory = $null }
if ($GSecurityDirectory) {
 $isoOverlay = Join-Path $GSecurityDirectory 'Iso'
 if (Test-Path -LiteralPath $isoOverlay -PathType Container) { $GSecurityDirectory = $isoOverlay }
 $GSecurityDirectory = (Resolve-Path -LiteralPath $GSecurityDirectory -ErrorAction Stop).Path
}
function Add-GDebloatDrivers([string]$MountPath) {
 if (-not $DriverDirectory) { return }
 & dism.exe /English "/Image:$MountPath" /Add-Driver "/Driver:$DriverDirectory" /Recurse
 if ($LASTEXITCODE -notin @(0,3010)) { throw "Driver injection failed: DISM $LASTEXITCODE. Image: $MountPath" }
}
function Enable-GDebloatLegacyFeatures([string]$MountPath, [string]$SourcePath) {
 $netfx = Get-WindowsOptionalFeature -Path $MountPath -FeatureName NetFx3 -ErrorAction Stop
 if ([string]$netfx.State -notin @('Enabled', 'EnablePending')) {
  if (-not $SourcePath -or -not (Test-Path -LiteralPath $SourcePath -PathType Container)) {
   throw 'NetFx3 is not enabled and matching sources\sxs is missing. Supply -NetFx3Source with matching Windows NetFx3 CABs.'
  }
  & dism.exe /English "/Image:$MountPath" /Enable-Feature /FeatureName:NetFx3 /All /LimitAccess "/Source:$SourcePath"
  if ($LASTEXITCODE -notin @(0,3010)) { throw "NetFx3 enable failed: DISM $LASTEXITCODE. Use source CABs matching this Windows image." }
 }
 & dism.exe /English "/Image:$MountPath" /Enable-Feature /FeatureName:DirectPlay /All /LimitAccess
 if ($LASTEXITCODE -notin @(0,3010)) { throw "DirectPlay enable failed: DISM $LASTEXITCODE" }
}
function Copy-GDebloatGSecurityOverlay([string]$OverlayPath, [string]$MediaPath) {
 if (-not $OverlayPath) { return }
 foreach ($item in @(Get-ChildItem -LiteralPath $OverlayPath -Force)) {
  if ($item.Name -in @('.git', 'boot', 'efi', 'bootmgr', 'bootmgr.efi', 'setup.exe')) { continue }
  if ($item.Name -ieq 'sources') {
   # Only OEM payloads may be added under sources; never replace setup images/providers.
   $oem = Join-Path $item.FullName '$OEM$'
   if (Test-Path -LiteralPath $oem -PathType Container) {
    Copy-Item -LiteralPath $oem -Destination (Join-Path $MediaPath 'sources') -Recurse -Force -ErrorAction Stop
   }
   continue
  }
  Copy-Item -LiteralPath $item.FullName -Destination $MediaPath -Recurse -Force -ErrorAction Stop
 }
}

$hostArchitecture = $Env:PROCESSOR_ARCHITECTURE
New-Item -ItemType Directory -Force -Path "$mainOSDrive\GDebloat\sources" >$null

# Robust ISO/source-drive input. Accepts E, E:, E:\, or a mounted-media path
do {
 if ($SourceIso) { $DriveInput = $SourceIso.Trim(); $SourceIso = $null }
 else { $DriveInput = (Read-Host "Please enter the drive letter for the Windows 11 image").Trim() }
 if ([string]::IsNullOrWhiteSpace($DriveInput)) {
 Write-Warning "No drive was entered. Please enter a mounted ISO drive such as E or E:."
 $DriveLetter = $null
 continue
 }

 # Accept a drive-letter form (E, E:, E:\).
 if ($DriveInput -match '^[A-Za-z]:?\\?$') {
 $DriveLetter = $DriveInput.Substring(0,1).ToUpperInvariant() + ':'
 }
 elseif ($DriveInput -match '^[A-Za-z]$') {
 $DriveLetter = $DriveInput.ToUpperInvariant() + ':'
 }
 else {
 Write-Warning "Invalid drive input '$DriveInput'. Enter only a mounted drive such as E or E:."
 $DriveLetter = $null
 continue
 }

 if (-not (Test-Path -LiteralPath ($DriveLetter + '\\') -PathType Container)) {
 Write-Warning "Drive $DriveLetter is not available. Mount the Windows ISO and try again."
 $DriveLetter = $null
 }
} while ($null -eq $DriveLetter)

# Validate the Windows installation media.
$sourceInstallWim = Join-Path $DriveLetter 'sources\install.wim'
$sourceInstallEsd = Join-Path $DriveLetter 'sources\install.esd'

if (-not (Test-Path -LiteralPath (Join-Path $DriveLetter 'sources\boot.wim') -PathType Leaf)) {
 throw "boot.wim was not found in: $DriveLetter\sources. Check that the mounted ISO is Windows installation media."
}

if ((Test-Path -LiteralPath $sourceInstallWim -PathType Leaf) -and (Test-Path -LiteralPath $sourceInstallEsd -PathType Leaf)) {
 # Prefer install.wim when both files exist.
 $sourceImagePath = $sourceInstallWim
}
elseif (Test-Path -LiteralPath $sourceInstallWim -PathType Leaf) {
 $sourceImagePath = $sourceInstallWim
}
elseif (Test-Path -LiteralPath $sourceInstallEsd -PathType Leaf) {
 $sourceImagePath = $sourceInstallEsd
}
else {
 throw "Neither install.wim nor install.esd was found in: $DriveLetter\sources"
}

if (-not $NetFx3Source) {
 foreach ($candidate in @((Join-Path $DriveLetter 'sources\sxs'), (Join-Path $PSScriptRoot 'NetFx3'), (Join-Path $PSScriptRoot 'sources\sxs'))) {
  if (Test-Path -LiteralPath $candidate -PathType Container) { $NetFx3Source = $candidate; break }
 }
}
Write-Host "Using source image: $sourceImagePath"
$index = $ImageIndex
if ($index -le 0) { $index = Select-WimImageIndex -ImagePath $sourceImagePath }
 # Determine the architecture of the selected Windows image.
 # Query the selected image directly first. Different DISM versions expose
 # architecture as x64/amd64, arm64, or numeric architecture IDs.
 $architecture = $null
 $rawArchitecture = $null

 try {
     $selectedImageInfo = Get-WindowsImage -ImagePath $sourceImagePath -Index $index -ErrorAction Stop
     if ($selectedImageInfo) {
         $rawArchitecture = [string]$selectedImageInfo.Architecture
     }
 } catch {
     $selectedImageInfo = $null
 }

 switch -Regex ($rawArchitecture) {
     '(?i)^(x64|amd64|9)$' { $architecture = 'amd64'; break }
     '(?i)^(arm64|12)$' { $architecture = 'arm64'; break }
     '(?i)^(x86|i386|0)$' { $architecture = 'x86'; break }
 }

 if (-not $architecture) {
     $dismInfo = & dism.exe /English /Get-WimInfo /WimFile:$sourceImagePath /Index:$index 2>&1
     $dismText = $dismInfo -join [Environment]::NewLine
     $archMatch = [regex]::Match($dismText, '(?im)^\s*Architecture\s*:\s*(x64|amd64|arm64|x86|i386|9|12|0)\s*$')
     if ($archMatch.Success) {
         $rawArchitecture = $archMatch.Groups[1].Value
         switch -Regex ($rawArchitecture) {
             '(?i)^(x64|amd64|9)$' { $architecture = 'amd64'; break }
             '(?i)^(arm64|12)$' { $architecture = 'arm64'; break }
             '(?i)^(x86|i386|0)$' { $architecture = 'x86'; break }
         }
     }
 }

 if (-not $architecture) {
     $allImageInfo = @(Get-WindowsImage -ImagePath $sourceImagePath -ErrorAction SilentlyContinue |
         Where-Object { [int]$_.ImageIndex -eq [int]$index } | Select-Object -First 1)
     if ($allImageInfo.Count -gt 0) {
         foreach ($propertyName in 'Architecture','ArchitectureName','Platform') {
             $prop = $allImageInfo[0].PSObject.Properties[$propertyName]
             if ($prop) {
                 $candidate = [string]$prop.Value
                 if ($candidate -match '(?i)^(x64|amd64|9)$') { $architecture = 'amd64'; break }
                 if ($candidate -match '(?i)^(arm64|12)$') { $architecture = 'arm64'; break }
                 if ($candidate -match '(?i)^(x86|i386|0)$') { $architecture = 'x86'; break }
             }
         }
     }
 }

 if (-not $architecture) {
     throw "Could not determine the architecture of selected Windows image Index $index. DISM/Get-WindowsImage did not return a recognized architecture."
 }

 Write-Host "Architecture: $architecture"

# Architecture compatibility flags used by architecture-sensitive cleanup blocks.
$isAmd64 = ($architecture -eq 'amd64')
$isArm64 = ($architecture -eq 'arm64')
$isX86   = ($architecture -eq 'x86')
$gDebloatBootPhase = $false

if (-not ($isAmd64 -or $isArm64 -or $isX86)) {
    throw "Unsupported Windows image architecture: $architecture"
}

# Architecture-aware cleanup guard.
# Keep the cleanup/compaction engines architecture-neutral while gating
# explicit architecture-specific payload paths.
function Test-Micro11CleanupPathForArchitecture {
    param([Parameter(Mandatory=$true)][string]$Path)

    # Only driver and registry exclusions differ from Micro in its boot file list.
    if ($gDebloatBootPhase) {
        # A whole-tree deletion would also remove its drivers and config hives.
        if ($Path -match '(?i)\\Windows\\SysWOW64\\?$') { return $false }
        if ($Path -match '(?i)\\(DriverStore|drivers|INF|config|Users|ProgramData|GroupPolicy|GroupPolicyUsers|SMI)(\\|$)') { return $false }
        if ($Path -match '(?i)(\\(NTUSER\.DAT|UsrClass\.dat)(\.|$)|\.(hiv|reg|pol|sys|inf|cat)$)') { return $false }
        if ($isArm64 -and $Path -match '(?i)(?:_amd64_|\\GAC_64\\|\\Framework64\\)') { return $false }
        if ($isAmd64 -and $Path -match '(?i)(?:_arm64_|\\GAC_Arm64\\|\\FrameworkArm64\\)') { return $false }
        return $true
    }
    if ($isArm64 -and $Path -match '(?i)(?:_amd64_|\\GAC_64\\|\\Framework64\\)') { return $false }
    if ($isAmd64 -and $Path -match '(?i)(?:_arm64_|\\GAC_Arm64\\|\\FrameworkArm64\\)') { return $false }
    # GDebloat exceptions to the original Micro deletion lists.
    if ($Path -match '(?i)\\(DriverStore|drivers|INF|config|servicing|Microsoft\.NET)(\\|$)') { return $false }
    if ($Path -match '(?i)\\(NTUSER\.DAT|UsrClass\.dat)(\.|$)|\.(hiv|reg|pol|sys|inf|cat)$') { return $false }
    if ($Path -match '(?i)\\assembly\\(GAC|GAC_32|GAC_64|GAC_MSIL)(\\|$)') { return $false }
    if ($Path -match '(?i)\\(Installer|Registration|AppRepository|CatRoot|catroot2|WinMetadata)(\\|$)') { return $false }
    if ($Path -match '(?i)\\SystemApps\\[^\\]*(Client\.(CBS|Core|Photon)|WindowsAppRuntime|ShellExperience|StartMenu|CloudExperience|AAD|AccountsControl|Xbox|Store|Gaming)') { return $false }
    if ($Path -match '(?i)\\(mf[^\\]*|wmv[^\\]*|wmp[^\\]*|wdma[^\\]*|hdaudio[^\\]*|portcls[^\\]*|devenum[^\\]*|xact[^\\]*|x3daudio[^\\]*|dplay[^\\]*|dpnet[^\\]*|dpnh[^\\]*|dpvoice[^\\]*|audio[^\\]*|audiosrv[^\\]*|mmdevapi[^\\]*|winmm[^\\]*|dsound[^\\]*|xaudio[^\\]*|xinput[^\\]*|msacm[^\\]*|mmcss[^\\]*|msiexec[^\\]*|msi\.dll|appx[^\\]*|appmodel[^\\]*|xbox[^\\]*|xbl[^\\]*|gaming[^\\]*|clip[^\\]*|licens[^\\]*|wlid[^\\]*|token[^\\]*|microsoftaccount[^\\]*|vcruntime[^\\]*|msvcp[^\\]*|ucrt[^\\]*)$') { return $false }
    return $true
}
# Silenced per-directory WinSxS copy message: "Copying Windows image..."
Copy-Item -Path "$DriveLetter\*" -Destination "$mainOSDrive\GDebloat" -Recurse -Force | Out-Null

$wimFilePath = Join-Path $mainOSDrive 'GDebloat\sources\install.wim'
$destinationEsdPath = Join-Path $mainOSDrive 'GDebloat\sources\install.esd'

if ($sourceImagePath -eq $sourceInstallEsd) {
 Write-Host ''
 Write-Host "Converting the selected install.esd image to install.wim. This may take a while..."

 if (Test-Path $wimFilePath) {
 Remove-Item -LiteralPath $wimFilePath -Force -ErrorAction Stop
 }

 & DISM /Export-Image `
 "/SourceImageFile:$sourceInstallEsd" `
 "/SourceIndex:$index" `
 "/DestinationImageFile:$wimFilePath" `
 /Compress:max /CheckIntegrity

 if ($LASTEXITCODE -ne 0) {
 throw "DISM failed to export install.esd to install.wim. Exit code: $LASTEXITCODE"
 }

 # The exported WIM contains only the selected image, so its index is always 1.
 $index = 1

 if (Test-Path $destinationEsdPath) {
 try {
 Set-ItemProperty -LiteralPath $destinationEsdPath -Name IsReadOnly -Value $false -ErrorAction SilentlyContinue
 Remove-Item -LiteralPath $destinationEsdPath -Force -ErrorAction SilentlyContinue
 }
 catch {
 Write-Warning "Could not remove install.esd: $($_.Exception.Message)"
 }
 }
}
else {
 # The source was already install.wim. Keep the selected index.
 if (-not (Test-Path $wimFilePath)) {
 throw "install.wim was not copied to: $wimFilePath"
 }
}


Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "INSTALL.WIM - PREPARATION AND MOUNTING" -ForegroundColor Yellow
Write-Host "  [Stage 1.1] Validate working files and image source" -ForegroundColor Cyan
Write-Host "  [Stage 1.2] Prepare temporary working directories" -ForegroundColor Green
Write-Host "  [Stage 1.3] Mount INSTALL.WIM" -ForegroundColor Green
Write-Host "  [Stage 1.4] Verify mounted image and servicing paths" -ForegroundColor Yellow
Write-Host "============================================================================" -ForegroundColor Gray
. {
Write-Host "Copy complete!"
# Performance optimization: cosmetic fixed delay removed.
# Clear-Host suppressed so section headers remain visible.

if (-not (Test-Path $wimFilePath)) {
 throw "The working install.wim was not found: $wimFilePath"
}

Write-Host "Getting image information:"
& DISM /English "/Get-WimInfo" "/WimFile:$wimFilePath"

if ($LASTEXITCODE -ne 0) {
 throw "DISM could not read the working install.wim. Exit code: $LASTEXITCODE"
}

Write-Host "Using Image Index: $index"
Write-Host "Mounting Windows image. This may take a while."

& takeown /F $wimFilePath >$null 2>&1
$takeownWimExitCode = $LASTEXITCODE
if ($takeownWimExitCode -ne 0) {
    Write-Warning "Could not take ownership of install.wim (takeown.exe exit code $takeownWimExitCode). Continuing, since the file may already be writable."
}

& icacls $wimFilePath /grant "$($adminGroup.Value):(F)" >$null 2>&1
$icaclsWimExitCode = $LASTEXITCODE
if ($icaclsWimExitCode -ne 0) {
    Write-Warning "Could not grant Administrators full control on install.wim (icacls.exe exit code $icaclsWimExitCode). Continuing, since the file may already be writable."
}

try {
 Set-ItemProperty -LiteralPath $wimFilePath -Name IsReadOnly -Value $false -ErrorAction Stop
}
catch {
 Write-Warning "Could not change the read-only attribute of install.wim: $($_.Exception.Message)"
}

Clear-EmptyMountDirectory -MountDir $scratchDir

& DISM /English `
 /Mount-Image `
 "/ImageFile:$wimFilePath" `
 "/Index:$index" `
 "/MountDir:$scratchDir"
$mountExitCode = $LASTEXITCODE

if ($mountExitCode -ne 0) {
 throw "DISM failed to mount the Windows image. Exit code: $mountExitCode"
}

if (-not $architecture) {
 Write-Host "Architecture information not found."
}

Write-Host 'Enabling .NET Framework 3.5 and DirectPlay in the installation image...'
Enable-GDebloatLegacyFeatures -MountPath $scratchDir -SourcePath $NetFx3Source
Add-GDebloatDrivers -MountPath $scratchDir

Write-Host "Taking ownership of the Program Files folder. This might take a while..."
& takeown.exe /F "$mainOSDrive\scratchDir\Program Files" /A /R /D Y >$null 2>&1
& icacls.exe "$mainOSDrive\scratchDir\Program Files" /grant "$($adminGroup.Value):(F)" /T /C /Q /L >$null 2>&1

$programFilesX86Path = "$mainOSDrive\scratchDir\Program Files (x86)"
if (Test-Path -LiteralPath $programFilesX86Path -PathType Container) {
    Write-Host "Taking ownership of the Program Files (x86) folder. This might take a while..."
    & takeown.exe /F $programFilesX86Path /A /R /D Y >$null 2>&1
    & icacls.exe $programFilesX86Path /grant "$($adminGroup.Value):(F)" /T /C /Q /L >$null 2>&1
}

Write-Host "Taking ownership of the ProgramData folder. This might take a while..."
& takeown.exe /F "$mainOSDrive\scratchDir\ProgramData" /A /R /D Y >$null 2>&1
& icacls.exe "$mainOSDrive\scratchDir\ProgramData" /grant "$($adminGroup.Value):(F)" /T /C /Q /L >$null 2>&1

Write-Host "Taking ownership of the Windows folder. This might take a while..."
& takeown.exe /F "$mainOSDrive\scratchDir\Windows" /A /R /D Y >$null 2>&1
& icacls.exe "$mainOSDrive\scratchDir\Windows" /grant "$($adminGroup.Value):(F)" /T /C /Q /L >$null 2>&1

Write-Host "Taking ownership of the RtBackup folder. This might take a while..."
& takeown.exe /F "$mainOSDrive\scratchDir\Windows\System32\LogFiles\WMI\RtBackup" /A /R /D Y >$null 2>&1
& icacls.exe "$mainOSDrive\scratchDir\Windows\System32\LogFiles\WMI\RtBackup" /grant "$($adminGroup.Value):(F)" /T /C /Q /L >$null 2>&1
Write-Host "Complete!"
} *> $null
Write-Host 'INSTALL.WIM preparation and mounting Completed...' -ForegroundColor Green



Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "INSTALL.WIM - PROVISIONED APP REMOVAL" -ForegroundColor Gray
Write-Host "  [Stage 2.1] Discover provisioned AppX packages" -ForegroundColor Gray
Write-Host "  [Stage 2.2] Remove unwanted provisioned applications" -ForegroundColor Cyan
Write-Host "  [Stage 2.3] Clean residual AppX package files" -ForegroundColor Cyan
Write-Host "  [Stage 2.4] Verify provisioned-app cleanup" -ForegroundColor Green
Write-Host "============================================================================" -ForegroundColor Gray
. {
Write-Host "Mounting complete! Performing removal of applications..." -ForegroundColor Green

# Retrieve provisioned packages cleanly using DISM with English output
$dismOutput = & dism /English "/image:$mainOSDrive\scratchdir" /Get-ProvisionedAppxPackages

$packages = @()
foreach ($line in $dismOutput) {
 if ($line -match '^\s*PackageName\s*:\s*(.+)$') {
 $packages += $Matches[1].Trim()
 }
}

# Keep only these runtime packages
$keepPrefixes = @(
 'Microsoft.WindowsStore_', 'Microsoft.StorePurchaseApp_', 'Microsoft.DesktopAppInstaller_',
 'Microsoft.GamingApp_', 'Microsoft.GamingServices_', 'Microsoft.Xbox',
 'Microsoft.VCLibs', 'Microsoft.NET.Native', 'Microsoft.UI.Xaml', 'Microsoft.WindowsAppRuntime',
 'Microsoft.Services.Store.Engagement', 'Microsoft.AV1', 'Microsoft.AVC', 'Microsoft.HEVC',
 'Microsoft.HEIF', 'Microsoft.VP9', 'Microsoft.WebMedia', 'Microsoft.Webp'
)

# Filter packages to remove
$packagesToRemove = foreach ($package in $packages) {
 $keep = $false
 foreach ($prefix in $keepPrefixes) {
 if ($package.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
 $keep = $true
 break
 }
 }
 if (-not $keep) {
 $package
 }
}

# Loop and remove unwanted provisioned packages. Keep an exact record of the
# packages DISM really removed so later registry garbage collection can use
# removal evidence instead of guessing from names alone.
$removedProvisionedAppxPackages = New-Object System.Collections.Generic.HashSet[string]([StringComparer]::OrdinalIgnoreCase)
foreach ($package in $packagesToRemove) {
 & dism /English `
 "/image:$mainOSDrive\scratchdir" `
 /Remove-ProvisionedAppxPackage `
 "/PackageName:$package" >$null 2>&1

 if ($LASTEXITCODE -ne 0) {
 Write-Warning "Failed to remove package: $package"
 }
 else {
 [void]$removedProvisionedAppxPackages.Add([string]$package)
 }
}

Write-Host "App removal process finished." -ForegroundColor Cyan

Write-Host "Attempting to remove leftover WindowsApps folders..."
foreach ($package in $removedProvisionedAppxPackages) {
 $folderPath = Join-Path "$scratchDir\Program Files\WindowsApps" $package

 if (Test-Path $folderPath) {
 Remove-Item $folderPath -Recurse -Force -ErrorAction SilentlyContinue
 }
}

Write-Host "Removing of system apps complete! Now proceeding to removal of system packages..."
} *> $null
Write-Host 'INSTALL.WIM provisioned app removal Completed...' -ForegroundColor Green


Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "INSTALL.WIM - SYSTEM PACKAGE AND FILE REMOVAL" -ForegroundColor Cyan
Write-Host "  [Stage 3.1] Discover removable system packages" -ForegroundColor Green
Write-Host "  [Stage 3.2] Remove system packages regardless of build number" -ForegroundColor Yellow
Write-Host "  [Stage 3.3] Remove associated component and payload files" -ForegroundColor Gray
Write-Host "  [Stage 3.4] Reduce WinSxS and servicing leftovers" -ForegroundColor Cyan
Write-Host "  [Stage 3.5] Clean scheduled-task and related residual files" -ForegroundColor Cyan
Write-Host "============================================================================" -ForegroundColor Gray
. {
# Performance optimization: cosmetic fixed delay removed.
# Clear-Host suppressed so section headers remain visible.

$packagePatterns = @(
"Microsoft-Windows-PowerShell-ISE-FOD-Package~",
"Microsoft-Windows-Telnet-Client-FOD-Package~",
"Microsoft-Windows-TerminalServices-AppServer-Client-FOD-Package~",
"Microsoft-Windows-Wifi-Client-Qualcomm-Athw8x-FOD-Package~",
"Microsoft-Windows-Wifi-Client-Realtek-Rtwlane-FOD-Package~",
"Microsoft-Windows-WMIC-FoD-Package~",
"Microsoft-Windows-Wifi-Client-Intel-Netwns64-FOD-Package~",
"Microsoft-Windows-Wifi-Client-Intel-Netwtw02-FOD-Package~",
"Microsoft-Windows-Wifi-Client-Intel-Netwtw08-FOD-Package~",
"Microsoft-Windows-Wifi-Client-Intel-Netwtw10-FOD-Package~",
"Microsoft-Windows-EnterpriseClientSync-Host-FOD-Package-wow64.cab",
"Microsoft-Windows-Notepad-System-FoD-Package~",
"Microsoft-Windows-StepsRecorder-Package-wow64.cab",
"Microsoft-Windows-Wifi-Client-Broadcom-Bcmwl63al-FOD-Package~",
"Microsoft-Windows-Wifi-Client-Qualcomm-Athwnx-FOD-Package~",
"Microsoft-Windows-Wifi-Client-Qualcomm-Qcamain10x64-FOD-Package~",
"Microsoft-Windows-MediaPlayer-Package~",
"Microsoft-Windows-TFTP-Client-FOD-Package~",
"Microsoft-Windows-Wifi-Client-Broadcom-Bcmwl63a-FOD-Package~",
"Microsoft-Windows-Wifi-Client-Intel-Netwew01-FOD-Package~",
"Microsoft-Windows-Wifi-Client-Marvel-Mrvlpcie8897-FOD-Package~",
"Microsoft-Windows-InternetExplorer-Optional-Package~",
"Microsoft-Windows-Kernel-LA57-FoD-Package~",
"Microsoft-Windows-PowerShell-ISE-FOD-Package-wow64.cab",
"Microsoft-Windows-Wifi-Client-Intel-Netwtw04-FOD-Package~",
"Microsoft-Windows-Wifi-Client-Realtek-Rtwlane13-FOD-Package~",
"Microsoft-Windows-Ethernet-Client-Intel-E2f68-FOD-Package~",
"Microsoft-Windows-LanguageFeatures-TextToSpeech-en-us-Package~",
"Microsoft-Windows-SmbDirect-FOD-Package~",
"Microsoft-Windows-TabletPCMath-Package~",
"Microsoft-Windows-Wifi-Client-Intel-Netwlv64-FOD-Package~",
"Microsoft-Windows-Wifi-Client-Realtek-Rtl8192se-FOD-Package~",
"Microsoft-Windows-Wifi-Client-Realtek-Rtwlane01-FOD-Package~",
"Microsoft-Windows-DirectoryServices-ADAM-Client-FOD-Package~",
"Microsoft-Windows-EnterpriseClientSync-Host-FOD-Package~",
"Microsoft-Windows-Hello-Face-Package~",
"Microsoft-Windows-MediaPlayer-Package-wow64.cab",
"Microsoft-Windows-SimpleTCP-FOD-Package~",
"Microsoft-Windows-Wifi-Client-Intel-Netwtw06-FOD-Package~",
"OpenSSH-Client-Package~",
"Microsoft-Edge-WebView-FOD-Package~",
"Microsoft-Windows-Ethernet-Client-Realtek-Rtcx21x64-FOD-Package~",
"Microsoft-Windows-ProjFS-OptionalFeature-FOD-Package~",
"Microsoft-Windows-StepsRecorder-Package~",
"Microsoft-Windows-TerminalServices-AppServer-Client-FOD-Package-wow64.cab",
"Microsoft-Windows-Wifi-Client-Intel-Netwbw02-FOD-Package~",
"Microsoft-Windows-Wifi-Client-Intel-Netwsw00-FOD-Package~",
"Microsoft-Windows-Wifi-Client-Ralink-Netr28x-FOD-Package~",
"Microsoft-Windows-WMIC-FoD-Package-wow64.cab",
"Microsoft-Windows-Ethernet-Client-Intel-E1i68x64-FOD-Package~",
"Microsoft-Windows-LanguageFeatures-Handwriting-en-us-Package~",
"Microsoft-Windows-LanguageFeatures-Speech-en-us-Package~",
"Microsoft-Windows-InternetExplorer-Optional-Package~31bf3856ad364e35",
"Microsoft-Windows-Kernel-LA57-FoD-Package~31bf3856ad364e35~amd64",
"Microsoft-Windows-LanguageFeatures-Handwriting-$languageCode-Package~31bf3856ad364e35",
"Microsoft-Windows-LanguageFeatures-Speech-$languageCode-Package~31bf3856ad364e35",
"Microsoft-Windows-LanguageFeatures-TextToSpeech-$languageCode-Package~31bf3856ad364e35",
"Microsoft-Windows-MediaPlayer-Package~31bf3856ad364e35",
"Windows-Defender-Client-Package~31bf3856ad364e35~",
"Microsoft-Windows-WordPad-FoD-Package~",
"Microsoft-Windows-MSPaint-FoD-Package~",
"Microsoft-Windows-SnippingTool-FoD-Package~",
"Microsoft-Windows-Xps-Xps-Viewer-Opt-Package~",
"*IME-ja-jp*",
"*IME-ko-kr*",
"*IME-zh-cn*",
"*IME-zh-tw*",
"Microsoft-Windows-Hello-BioEnrollment-Package~",
"Microsoft-Windows-BitLocker-DriveEncryption-FVE-Package~",
"Microsoft-Windows-TPM-WMI-Provider-Package~",
"Microsoft-Windows-Narrator-App-Package~",
"Microsoft-Windows-Magnifier-App-Package~"

)

$packagePatterns = @($packagePatterns | Where-Object { $_ -notmatch '(?i)(Ethernet|Wifi|Wlan|Audio|Xbox|Gaming|Store|Appx|NetFx|DotNet|DirectPlay|LegacyComponents|Installer|BitLocker|TPM-WMI|Hello-BioEnrollment)' })

# Do not target package identities explicitly bound to a different native architecture.
# Architecture-neutral and WOW64 package patterns are intentionally retained.
if ($isArm64) {
    $packagePatterns = @($packagePatterns | Where-Object { $_ -notmatch '(?i)~amd64(?:~|$)' })
}
elseif ($isAmd64) {
    $packagePatterns = @($packagePatterns | Where-Object { $_ -notmatch '(?i)~arm64(?:~|$)' })
}

# Discover exact installed/staged package identities from the TARGET image.
# No build/version is hard-coded into the identity used for Remove-Package.
$packageListOutput = @(& dism /English "/image:$scratchDir" /Get-Packages /Format:List 2>&1)
$packageListExitCode = $LASTEXITCODE
if ($packageListExitCode -ne 0) {
 throw "DISM /Get-Packages failed while discovering target package identities. Exit code: $packageListExitCode"
}

# Parse the TARGET image package inventory, including package state.
# IMPORTANT: package identities are taken from the target image itself. No
# host/DISM build number is ever substituted into a package identity.
$targetPackages = New-Object System.Collections.Generic.List[object]
$currentIdentity = $null
$currentState = $null
foreach ($line in $packageListOutput) {
 $s = [string]$line

 if ($s -match '^\s*Package Identity\s*:\s*(\S+).*$') {
 if ($currentIdentity) {
 [void]$targetPackages.Add([pscustomobject]@{
 Identity = $currentIdentity
 State = if ($currentState) { $currentState } else { 'Unknown' }
 })
 }
 $currentIdentity = $Matches[1].Trim()
 $currentState = $null
 continue
 }

 if ($currentIdentity -and $s -match '^\s*State\s*:\s*(.+?)\s*$') {
 $currentState = $Matches[1].Trim()
 }
}
if ($currentIdentity) {
 [void]$targetPackages.Add([pscustomobject]@{
 Identity = $currentIdentity
 State = if ($currentState) { $currentState } else { 'Unknown' }
 })
}

# De-duplicate identities case-insensitively while retaining the first state.
$installedPackageIdentities = New-Object System.Collections.Generic.List[string]
$packageStates = @{}
foreach ($package in $targetPackages) {
 $identity = [string]$package.Identity
 if (-not $identity) { continue }
 if (-not $packageStates.ContainsKey($identity)) {
 $packageStates[$identity] = [string]$package.State
 [void]$installedPackageIdentities.Add($identity)
 }
}

$matchedPackageIdentities = New-Object System.Collections.Generic.HashSet[string]([StringComparer]::OrdinalIgnoreCase)
$removedPackageIdentities = New-Object System.Collections.Generic.HashSet[string]([StringComparer]::OrdinalIgnoreCase)
$skippedSupersededPackages = New-Object System.Collections.Generic.HashSet[string]([StringComparer]::OrdinalIgnoreCase)
$expected0805Packages = New-Object System.Collections.Generic.HashSet[string]([StringComparer]::OrdinalIgnoreCase)
$packageRemovalFailures = New-Object System.Collections.Generic.List[object]

foreach ($packagePattern in $packagePatterns) {
 # package-match fix: normalize configured package names into
 # build-independent prefix matches so version/build suffixes do not
 # prevent discovery of the actual installed package identity.
 $matchPattern = [string]$packagePattern
 if ($matchPattern -match '(?i)\.cab$') {
 $matchPattern = $matchPattern -replace '(?i)\.cab$', ''
 }
 if ($matchPattern -notmatch '[*?]') {
 $matchPattern = $matchPattern + '*'
 }

 $matches = @($installedPackageIdentities | Where-Object { $_ -like $matchPattern })
 foreach ($packageIdentity in $matches) {
 $state = [string]$packageStates[$packageIdentity]

 # Superseded packages are already replaced in the target image. Trying
 # to remove those stale identities is a common source of 0x800f0805.
 if ($state -match '(?i)superseded') {
 [void]$skippedSupersededPackages.Add($packageIdentity)
 continue
 }

 if (-not $matchedPackageIdentities.Add($packageIdentity)) { continue }

 # The exact identity comes from /Get-Packages on THIS image. This is
 # deliberately build-independent: 19045/26100/26200/26300/29651
 # targets can all be serviced by the same host DISM binary.
 & dism /English "/image:$scratchDir" /Remove-Package "/PackageName:$packageIdentity" /NoRestart >$null 2>&1
 $removeExitCode = $LASTEXITCODE
 if ($removeExitCode -eq 0) {
 [void]$removedPackageIdentities.Add($packageIdentity)
 }
 else {
 # Keep the normal console clean, but retain the exact DISM result for
 # every unsuccessful package-removal attempt. This is especially useful
 # when comparing AMD64 and ARM64 package behavior.
 $exitCodeUnsigned = [BitConverter]::ToUInt32([BitConverter]::GetBytes([int]$removeExitCode), 0)

 # Classify the two recurring CBS results seen in ARM64 diagnostics.
 # This classification is architecture-neutral and therefore also applies
 # to AMD64 when DISM returns the same codes.
 if ($removeExitCode -eq -2146498555) {
     # Expected 0x800F0805; classify silently and exclude from genuine failures.
     [void]$expected0805Packages.Add($packageIdentity)
     continue
 }
 $failureClass = 'Other DISM package-removal failure'
 if ($removeExitCode -eq -2146498523) {
     # 0x800F0825
     $failureClass = 'Known non-removable package state'
 }

 [void]$packageRemovalFailures.Add([pscustomobject]@{
 PackageIdentity = $packageIdentity
 State           = $state
 ExitCode        = [int]$removeExitCode
 ExitCodeHex     = ('0x{0:X8}' -f $exitCodeUnsigned)
 Classification  = $failureClass
 })
 }
 }
}

# Keep one concise package-removal summary line; suppress routine per-package diagnostics.
Write-Host ("Target package identities discovered: {0}; matched for removal: {1}; removed: {2}; failed/non-removable: {3}; superseded skipped: {4}" -f `
    $installedPackageIdentities.Count,
    $matchedPackageIdentities.Count,
    $removedPackageIdentities.Count,
    $packageRemovalFailures.Count,
    $skippedSupersededPackages.Count) -ForegroundColor Cyan

Write-Host "Removing pre-compiled .NET assemblies (Native Images)..."
Remove-Item -Path "$scratchDir\Windows\assembly\NativeImages_*" -Recurse -Force -ErrorAction SilentlyContinue

Write-Host "Performing aggressive manual file deletions..."
$winDir = "$scratchDir\Windows"
Write-Host "Slimming the DriverStore... (removing non-essential driver classes)"
$driverRepo = Join-Path -Path $winDir -ChildPath "System32\DriverStore\FileRepository"
$patternsToRemove = @(
 'prn*', # Printer drivers (e.g., prnms001.inf, prnge001.inf)
 'scan*', # Scanner drivers
 'mfd*', # Multi-function device drivers
 'wscsmd.inf*', # Smartcard readers
 'tapdrv*' # Tape drives
)

# Get all driver packages and remove the ones matching the patterns
Get-ChildItem -Path $driverRepo -Directory | ForEach-Object {
 $driverFolder = $_.Name
 foreach ($pattern in $patternsToRemove) {
 if ($driverFolder -like $pattern) {
  Remove-Item -Path $_.FullName -Recurse -Force
 break # Move to the next folder once a match is found
 }
 }
}

