Write-Host "  [Stage 2] 29.2 Build bootable ISO" -ForegroundColor Green
Write-Host "  [Stage 3] 29.3 Verify ISO output" -ForegroundColor Yellow
Write-Host "============================================================================" -ForegroundColor Gray

Write-Host "The GDebloat image is now completed. Proceeding with the making of the ISO..."
Write-Host "Creating ISO image..."

$script:EmbeddedOscdimgBase64 = @'

'@

$localOSCDIMGPath = if ($OscdimgPath) { $OscdimgPath } else { Join-Path ([IO.Path]::GetTempPath()) ('GDebloat-oscdimg-' + [guid]::NewGuid().ToString('N') + '.exe') }
if (-not $OscdimgPath) {
 [IO.File]::WriteAllBytes($localOSCDIMGPath, [Convert]::FromBase64String($script:EmbeddedOscdimgBase64))
 if ((Get-FileHash -LiteralPath $localOSCDIMGPath -Algorithm SHA256).Hash -ne 'F5129F313ED7EB46F2677CF522E64264A225F226307ED0DDB52BB14C46E7CFDD') { throw 'Embedded oscdimg checksum mismatch.' }
}
$OSCDIMG = $localOSCDIMGPath
Copy-GDebloatGSecurityOverlay -OverlayPath $GSecurityDirectory -MediaPath (Join-Path $mainOSDrive 'GDebloat')
$isoSourcePath = Join-Path $mainOSDrive 'GDebloat'
$isoOutputPath = $OutputIso
New-Item -ItemType Directory -Path (Split-Path -Parent $isoOutputPath) -Force | Out-Null
$oscdimgStdOut = Join-Path $env:TEMP ('Micro11_OSCDIMG_stdout_{0}.log' -f $PID)
$oscdimgStdErr = Join-Path $env:TEMP ('Micro11_OSCDIMG_stderr_{0}.log' -f $PID)
$oscdimgFailed = $false

try {
    if (-not (Test-Path -LiteralPath $OSCDIMG -PathType Leaf)) {
        throw "oscdimg.exe was not found at: $OSCDIMG"
    }
    if (-not (Test-Path -LiteralPath $isoSourcePath -PathType Container)) {
        throw "ISO source directory was not found: $isoSourcePath"
    }

    $biosBootFile = Join-Path $isoSourcePath 'boot\etfsboot.com'
    $uefiBootFile = Join-Path $isoSourcePath 'efi\microsoft\boot\efisys.bin'
    if (-not (Test-Path -LiteralPath $biosBootFile -PathType Leaf)) {
        throw "BIOS boot image was not found: $biosBootFile"
    }
    if (-not (Test-Path -LiteralPath $uefiBootFile -PathType Leaf)) {
        throw "UEFI boot image was not found: $uefiBootFile"
    }

    Remove-Item -LiteralPath $oscdimgStdOut, $oscdimgStdErr -Force -ErrorAction SilentlyContinue
    Remove-Item -LiteralPath $isoOutputPath -Force -ErrorAction SilentlyContinue

    # A single argument string avoids Start-Process/ArgumentList quoting problems
    # with source/output paths containing spaces.
    $bootData = '-bootdata:2#p0,e,b"{0}"#pEF,e,b"{1}"' -f $biosBootFile, $uefiBootFile
    $oscdimgArgumentString = '-m -o -u2 -udfver102 -l"GDebloat" {0} "{1}" "{2}"' -f `
        $bootData, $isoSourcePath, $isoOutputPath

    $oscdimgProcess = Start-Process `
        -FilePath $OSCDIMG `
        -ArgumentList $oscdimgArgumentString `
        -RedirectStandardOutput $oscdimgStdOut `
        -RedirectStandardError $oscdimgStdErr `
        -Wait `
        -PassThru `
        -WindowStyle Hidden `
        -ErrorAction Stop

    $oscdimgExitCode = [int]$oscdimgProcess.ExitCode
    if ($oscdimgExitCode -ne 0) {
        $details = @()
        foreach ($logPath in @($oscdimgStdErr, $oscdimgStdOut)) {
            if (Test-Path -LiteralPath $logPath -PathType Leaf) {
                $content = Get-Content -LiteralPath $logPath -Raw -ErrorAction SilentlyContinue
                if (-not [string]::IsNullOrWhiteSpace($content)) {
                    $details += $content.Trim()
                }
            }
        }
        if ($details.Count -gt 0) {
            throw ("OSCDIMG failed with exit code {0}.`n{1}" -f $oscdimgExitCode, ($details -join "`n"))
        }
        throw "OSCDIMG failed with exit code $oscdimgExitCode."
    }

    if (-not (Test-Path -LiteralPath $isoOutputPath -PathType Leaf)) {
        throw 'OSCDIMG returned exit code 0, but the output ISO was not created.'
    }

    $isoFile = Get-Item -LiteralPath $isoOutputPath -ErrorAction Stop
    if ($isoFile.Length -le 0) {
        throw 'OSCDIMG returned exit code 0, but the output ISO is empty.'
    }

    Remove-Item -LiteralPath $oscdimgStdOut, $oscdimgStdErr -Force -ErrorAction SilentlyContinue
    Write-Host ("ISO creation Completed... {0:N2} GB" -f ($isoFile.Length / 1GB)) -ForegroundColor Green
    Write-Host ("ISO: {0}" -f $isoFile.FullName) -ForegroundColor Green
}
catch {
    $oscdimgFailed = $true
    Write-Host ""
    Write-Host ("ISO creation FAILED: {0}" -f $_.Exception.Message) -ForegroundColor Red
    Write-Host 'The build has stopped before final working-file cleanup.' -ForegroundColor Red
    Write-Host ("ISO source tree preserved at: {0}" -f $isoSourcePath) -ForegroundColor Yellow
    if (Test-Path -LiteralPath $oscdimgStdErr -PathType Leaf) {
        Write-Host ("OSCDIMG stderr log preserved at: {0}" -f $oscdimgStdErr) -ForegroundColor Yellow
    }
    if (Test-Path -LiteralPath $oscdimgStdOut -PathType Leaf) {
        Write-Host ("OSCDIMG stdout log preserved at: {0}" -f $oscdimgStdOut) -ForegroundColor Yellow
    }
}

if ($oscdimgFailed) {
    try { Stop-Transcript | Out-Null } catch {}
    exit 1
}

Write-Host "Creation completed! Press Enter to continue..." -ForegroundColor Gray
# No completion prompt required.

Write-Host ""
Write-Host "============================================================================" -ForegroundColor Gray
Write-Host "FINAL WORKING-FILE CLEANUP" -ForegroundColor Green
Write-Host "  [Stage 1] 30.1 Remove temporary working files" -ForegroundColor Gray
Write-Host "  [Stage 2] 30.2 Remove temporary mount/servicing artifacts" -ForegroundColor Cyan
Write-Host "  [Stage 3] 30.3 Verify final workspace" -ForegroundColor Cyan
Write-Host "  [Stage 4] 30.4 Final completion" -ForegroundColor Green
Write-Host "============================================================================" -ForegroundColor Gray
. {
Remove-Item -Path "$mainOSDrive\GDebloat" -Recurse -Force >$null
Remove-Item -Path "$mainOSDrive\scratchdir" -Recurse -Force >$null
} *> $null
Write-Host "Final working-file cleanup Completed..." -ForegroundColor Cyan

if (-not $OscdimgPath) { Remove-Item -LiteralPath $localOSCDIMGPath -Force -ErrorAction SilentlyContinue }
# Stop the transcript
Stop-Transcript

exit
